using System;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Tests;

public sealed class DbFixture : IDisposable
{
    public string Connection { get; } = "memory";
    public void Dispose() { }
}

/// <summary>
/// Shared fixture holder replacing xUnit's ICollectionFixture.
/// Both test classes reference this to share a single DbFixture instance
/// and are marked [DoNotParallelize] so they never run concurrently.
/// </summary>
[TestClass]
public class DbCollection
{
    internal static DbFixture Fixture { get; private set; } = null!;

    [AssemblyInitialize]
    public static void AssemblyInit(TestContext _) => Fixture = new DbFixture();

    [AssemblyCleanup]
    public static void AssemblyCleanup() => Fixture?.Dispose();
}

